# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps


def spans(*texts):
    return [parse_span(text) for text in texts]


OPEN = parse_span("09:00-17:00")


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        got = find_gaps(
            spans("09:00-12:00", "13:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(got, ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        got = find_gaps(
            spans("10:00-11:00"), parse_span("09:00-12:00")
        )
        want = ["gap 09:00-10:00 (60 min)"]
        want.append("gap 11:00-12:00 (60 min)")
        self.assertEqual(got, want)

    def test_overlaps_and_full_cover_leave_no_gap(self):
        got = find_gaps(
            spans("09:00-13:00", "12:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(got, [])

    def test_nobody_working_is_one_gap(self):
        got = find_gaps([], parse_span("09:00-10:30"))
        self.assertEqual(got, ["gap 09:00-10:30 (90 min)"])

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-10:00"), OPEN)
